    drawIcon(ctx2, "home", 48, hy + 20, 18, hHover ? THEME.TX1 : THEME.TX2);
    drawText(ctx2, "\u4E3B\u9875", 48, hy + 44, { size: 10.5, color: hHover ? THEME.TX1 : THEME.TX2, align: "center" });
