  function pick2(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
  }
  function generateChinesePlayerName(usedNames) {
    for (let attempt = 0; attempt < 20; attempt++) {
      const surname = pick2(SURNAMES);
      const isCompound = surname.length > 1;
      const twoCharGiven = !isCompound && Math.random() < 0.65;
      const c1 = pick2(MALE_CHARS);
      let name;
      if (twoCharGiven) {
        let c2 = pick2(MALE_CHARS);
        if (c2 === c1) c2 = pick2(MALE_CHARS);
        name = `${surname}${c1}${c2}`;
      } else {
        name = `${surname}${c1}`;
      }
      if (!usedNames || !usedNames.has(name)) {
        usedNames?.add(name);
        return name;
      }
    }
    return `${pick2(SURNAMES)}${pick2(MALE_CHARS)}${pick2(MALE_CHARS)}`;
  }
  function generateFictionalClubName(usedNames) {
    const themeKeys = Object.keys(TEAM_THEMES);
    for (let attempt = 0; attempt < 40; attempt++) {
      const reg = pick2(REGIONAL_KEYWORDS);
      const theme = pick2(TEAM_THEMES[pick2(themeKeys)]);
      const suffix = pick2(TEAM_SUFFIXES);
      const roll = Math.random();
      const name = roll < 0.4 ? `${reg.region}${theme}${suffix}` : roll < 0.68 ? `${pick2(reg.keywords)}${theme}${suffix}` : roll < 0.86 ? `${reg.region}${pick2(reg.keywords)}${suffix}` : `${pick2(TEAM_MODIFIERS)}${reg.region}${theme}${suffix}`;
      if (!usedNames || !usedNames.has(name)) {
        usedNames?.add(name);
        return name;
      }
    }
    return `${pick2(REGIONAL_KEYWORDS).region}${pick2(TEAM_THEMES.glory)}${pick2(TEAM_SUFFIXES)}`;
  }

