      counterElements: ["press", "blitz"],
      counterStyles: ["gegenpress", "counter"],
      oppDebuff: { targetLine: "ALL", composurePenalty: 5, passingPenalty: 3, label: "\u5BF9\u624B\u66F4\u8863\u5BA4\u5931\u548C -5\u51B7" },
