        drawButton(ctx2, hits, cx - 150, 526, 300, 48, `\u6495\u5F00${meta.badge.split("\xB7")[1].trim()}\u5305 \u25B6`, ripNow, {
          variant: "gold",
          fontSize: 15,
          icon: "sparkle"
        });
        hits.add(cx - 140, cy - 160, 280, 320, ripNow);
        this.renderPickedSummaryBar(ctx2, club.squad, cpd.pickedCores);
