              this.modalBanner = this.selectedBenchId ? `\u5DF2\u9009\u4E2D\u66FF\u8865\u3010${sub.name}\u3011\uFF1A\u8BF7\u5728\u4E2D\u95F4\u7403\u573A\u70B9\u51FB\u8981\u66FF\u6362\u4E0B\u573A\u7684\u9996\u53D1\u7403\u5458\uFF01` : "\u5DF2\u53D6\u6D88\u9009\u4E2D\u66FF\u8865\uFF0C\u53EF\u91CD\u65B0\u9009\u4EBA\u6362\u4EBA";
