      drawText(ctx2, `${st.awayFormation} \xB7 ${TACTICAL_PRESETS[st.awayStyle].name}`, ax + cardW - 118, cy + 52, {
        size: 13,
        color: "#7DD3FC",
        align: "right"
      });
      const vsScale = easeOutBack(Math.min(1, Math.max(0, (t - 0.16) / 0.4)));
      ctx2.save();
      ctx2.translate(cx, cy + 26);
      ctx2.scale(vsScale, vsScale);
      drawRoundRect(ctx2, -44, -44, 88, 88, 44, "#0B111E", THEME.FLAME, 3);
      drawRoundRect(ctx2, -40, -40, 80, 80, 40, "#0B111E", THEME.GOLD_LIGHT, 1.5);
