      const outcomeTitle = isWin ? "\u7EC8\u573A\u54E8\u54CD \xB7 \u80DC\u5229\u6536\u5165\u56CA\u4E2D\uFF01" : isDraw ? "\u7EC8\u573A\u54E8\u54CD \xB7 \u5404\u53D6\u4E00\u5206\u63E1\u624B\u8A00\u548C" : "\u7EC8\u573A\u54E8\u54CD \xB7 \u867D\u8D25\u72B9\u8363\u6574\u88C5\u518D\u6218";
