      const narrativeTag = hasLateWin ? "\u8BFB\u79D2\u7EDD\u6740\u9AD8\u5149\u591C!" : isWin && opG === 0 ? "\u94C1\u95F8\u96F6\u5C01\u5B8C\u80DC!" : isWin && myG - opG >= 3 ? "\u706B\u529B\u5168\u5F00\u5927\u80DC\u6A2A\u626B!" : isDraw ? "\u7126\u707C\u93D6\u6218 \xB7 \u5BF8\u571F\u5FC5\u4E89" : "\u8D5B\u540E\u590D\u76D8 \xB7 \u9886\u53D6\u8865\u5F3A\u76F2\u76D2";
      const cx = THEME.W / 2;
